def svf(x,tau=0.02,dt=0.001,order=3):
    a=dt/tau;ys=[x]
    for i in range(order): ys.append(lfilter([a],[1,-(1-a)],ys[-1]))
    # return F x , s F x, s^2 F x with F=1/(tau s+1)^order
    y3=ys[3];y2=ys[2];y1=ys[1]
