D=pickle.load(open('D.pkl','rb'))
TR=['A_amb_op1','A_vref_op1','A_line_op3','A_gentrip_op1','A_load_op2']
def pll(th,Kp,Ki):
    # linear PLL: thp/th = (w0 Kp s + w0 Ki)/(s^2 + w0 Kp s + w0 Ki)
    w0=377.
    if Ki>0: b,a=bilinear([w0*Kp,w0*Ki],[1,w0*Kp,w0*Ki],1000)
    else: b,a=bilinear([w0*Kp],[1,w0*Kp],1000)
    return th[0]+lfilter(b,a,th-th[0])
dec=2
def oe(c,U,Y,na,nb):
    a=np.r_[1,c[:na]];b=c[na:].reshape(len(U),nb)
    return sum(lfilter(b[j],a,U[j]) for j in range(len(U)))+Y[0]-Y
def score_iq(Kp,Ki,show=False):
    cache={}
    for k in TR:
        d=D[k]
        th=d.bus_angle_rad.values;V=d.voltage_pu.values
        thp=pll(th,Kp,Ki)
        S=(d.active_power_pu.values+1j*d.reactive_power_pu.values)/V*np.exp(-1j*(th-thp))
        Iq=S.imag[::dec];Vd=V[::dec];Vs=d.voltage_setpoint_pu.values[::dec]
        cache[k]=([Vd-Vd[0],Vs-Vs[0]],Iq)
    na,nb=3,4
    X=[];Y=[]
    for k in TR:
        U,Q=cache[k];n=len(Q);k0=max(na,nb);y=Q-Q[0]
        cols=[-y[k0-i:n-i] for i in range(1,na+1)]
        for u in U: cols+=[u[k0-i:n-i] for i in range(0,nb)]
        X.append(np.column_stack(cols));Y.append(y[k0:])
    c0,*_=np.linalg.lstsq(np.vstack(X),np.concatenate(Y),rcond=None)
    best=None
    for trial in range(3):
        if trial>0:
            rng=np.random.default_rng(trial);c0=c0.copy();c0[:na]=np.poly(rng.uniform(0.5,0.999,na))[1:]
        try:
            r=least_squares(lambda c: np.concatenate([oe(c,*cache[k],na,nb)[::2] for k in TR]),c0,method='lm',max_nfev=800)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    return [np.sqrt(np.mean(oe(best.x,*cache[k],na,nb)**2))/np.std(cache[k][1]) for k in TR]
for Kp,Ki in [(100,0),(0.1,0),(0.05,0),(0.02,0),(0.05,0.5),(0.05,2)]:
    print(Kp,Ki,np.round(score_iq(Kp,Ki),3))

